import axios from "axios";
import { MDBDataTable } from "mdbreact";
import MUIDataTable from "mui-datatables";
import React, { Component } from "react";
import {
  MdAddCircle,
  MdCheckCircle,
  MdEdit,
  MdRemoveCircle
} from "react-icons/md";
import { connect } from "react-redux";
import { Button, Card, CardBody, CardHeader, Input, Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";

class Clients extends Component {
  state = {
    addRow: false,
    rowData: [],
    clientsLoaded: false
  };
  componentDidMount() {
    this.retrieveClients();
  }
  addRow = () => {
    const aR = this.state.rowData;
    if (!this.state.addRow) {
      aR.unshift({
        _id: "Auto Generated",
        name: <Input></Input>,
        createdBy: this.props.auth.isAuthenticated
          ? this.props.auth.user.name
          : "Guest",
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.addClient}
            >
              <MdCheckCircle />
            </Button>
          </div>
        )
      });
    } else {
      aR.splice(0, 1);
    }

    this.setState(state => ({
      addRow: !state.addRow,
      rowData: aR,
      rowData: state.rowData
    }));
  };

  retrieveClients = () => {
    console.log("loading");
    this.setState(state => ({
      addRow: state.addRow,
      clientsLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData = res.data.map(function(val, index) {
          return {
            _id: val._id,
            name: val.name,
            createdByUserId: val.createdByUserId.name,
            actions: (
              <div>
                <Button className="float-left" color="dark">
                  <MdEdit />
                </Button>
                <Button className="float-left" style={{ marginLeft: "0.2rem" }}>
                  <MdRemoveCircle />
                </Button>
              </div>
            )
          };
        });

        this.setState(state => ({
          addRow: state.addRow,
          clientsLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  addClient = () => {
    console.log("add");
    const newClient = {
      name: "test client",
      userId: this.props.auth.isAuthenticated
        ? this.props.auth.user._id
        : "Guest"
    };
    axios
      .post("/api/clients", newClient, tokenConfig(store.getState))
      .then(res => console.log(res.data))
      .catch(err => console.log(err.data));
  };

  removeClient = () => {
    console.log("remove");
  };

  render() {
    /*const data = {
      columns: [
        {
          label: "Id",
          field: "_id",
          sort: "asc"
        },
        {
          label: "Client Name",
          field: "name",
          sort: "asc"
        },
        {
          label: "Created By",
          field: "createdByUserId",
          sort: "asc"
        },
        {
          label: "Actions",
          field: "actions",
          sort: "asc"
        }
      ],
      rows: this.state.rowData
    };*/
    const columns = ["Name", "Company", "City", "State"];

    const data = [
      ["Joe James", "Test Corp", "Yonkers", "NY"],
      ["John Walsh", "Test Corp", "Hartford", "CT"],
      ["Bob Herm", "Test Corp", "Tampa", "FL"],
      ["James Houston", "Test Corp", "Dallas", "TX"]
    ];

    const options = {
      filterType: "checkbox"
    };

    return (
      <Card>
        <CardHeader>
          <h4 className="float-left">Clients</h4>
          <Button
            className="float-right"
            color="dark"
            onClick={this.removeClient}
          >
            <MdAddCircle />
          </Button>
        </CardHeader>
        <CardBody>
          {this.state.clientsLoaded ? (
            //<MDBDataTable striped bordered hover data={data} />
            <MUIDataTable
              title={"Employee List"}
              data={data}
              columns={columns}
              options={options}
            />
          ) : (
            <div
              style={{
                display: "flex",
                justifyContent: "center"
              }}
            >
              <Spinner animation="border" />
            </div>
          )}
        </CardBody>
      </Card>
    );
  }
}

const mapStateToProps = state => ({
  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

//export default connect(mapStateToProps, {postClient,getClients,deleteClient})(Clients);
export default connect(mapStateToProps, null)(Clients);
